379	// CreateInvite invites an email address to join an organization with a role. An invite to a role other than viewer holds
380	// a seat, so it is refused with a *SeatLimitError when none is free. Accepting an invite never needs a seat.
381	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
382		email = strings.TrimSpace(email)
383		if !validEmail(email) {
384			return Invite{}, invalid("an invite needs a valid email address")
385		}
386		if !role.Valid() || role == RoleOwner {
387			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
388		}
389		s.mu.Lock()
390		defer s.mu.Unlock()
391		if _, ok := s.orgs[orgID]; !ok {
392			return Invite{}, ErrNotFound
393		}
394		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
395			if _, member := s.members[memberKey{orgID, uid}]; member {
396				return Invite{}, ErrAlreadyMember
397			}
398		}
399		if role != RoleViewer {
400			if err := s.requireSeatLocked(orgID); err != nil {
401				return Invite{}, err
402			}
403		}
404		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
405		s.invites[inv.ID] = inv
406		return inv, nil
407	}
408	
409	// Invite returns one of an organization's invites.
410	func (s *Store) Invite(orgID, id string) (Invite, bool) {
411		s.mu.Lock()
412		defer s.mu.Unlock()
413		inv, ok := s.invites[id]
414		if !ok || inv.OrgID != orgID {
415			return Invite{}, false
416		}
417		return inv, true
418	}
