420	// Invites returns an organization's invites that were neither accepted nor revoked, oldest first.
421	func (s *Store) Invites(orgID string) []Invite {
422		s.mu.Lock()
423		defer s.mu.Unlock()
424		out := []Invite{}
425		for _, inv := range s.invites {
426			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
427				out = append(out, inv)
428			}
429		}
430		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
431		return out
432	}
