434	// RevokeInvite withdraws an invite.
435	func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
436		s.mu.Lock()
437		defer s.mu.Unlock()
438		inv, ok := s.invites[id]
439		if !ok || inv.OrgID != orgID {
440			return Invite{}, ErrNotFound
441		}
442		if inv.RevokedAt == nil {
443			t := now.UTC()
444			inv.RevokedAt = &t
445			s.invites[id] = inv
446		}
447		return inv, nil
448	}
