450	// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
451	// makes them a member with the invite's role and gives them a first API key.
452	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
453		s.mu.Lock()
454		defer s.mu.Unlock()
455		var inv Invite
456		found := false
457		for _, i := range s.invites {
458			if i.Token == token && token != "" {
459				inv, found = i, true
460				break
461			}
462		}
463		if !found || inv.RevokedAt != nil {
464			return User{}, Member{}, APIKey{}, ErrNotFound
465		}
466		var u User
467		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
468			u = s.users[id]
469		} else {
470			name = strings.TrimSpace(name)
471			if name == "" {
472				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
473			}
474			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
475			s.users[u.ID] = u
476			s.usersByEmail[normEmail(u.Email)] = u.ID
477		}
478		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
479		if err != nil {
480			return User{}, Member{}, APIKey{}, err
481		}
482		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
483		if err != nil {
484			return User{}, Member{}, APIKey{}, err
485		}
486		t := now.UTC()
487		inv.AcceptedAt = &t
488		s.invites[inv.ID] = inv
489		return u, m, k, nil
490	}
