191		if !decode(w, r, &in) {
192			return
193		}
194		u, m, k, err := s.store.AcceptInvite(in.Token, in.Name, s.clock.Now())
195		if err != nil {
196			if errors.Is(err, store.ErrNotFound) {
197				writeError(w, http.StatusNotFound, "invite_not_found", "no such invite")
198				return
199			}
200			s.storeError(w, err)
201			return
202		}
203		writeJSON(w, http.StatusCreated, map[string]any{"user": u, "member": s.memberView(m), "api_key": k})
204	}
205	
206	func (s *Server) listAPIKeys(w http.ResponseWriter, r *http.Request, p auth.Principal) {
207		writeJSON(w, http.StatusOK, list{Items: s.store.APIKeys(p.OrgID)})
208	}
